if __name__ == "__main__":
    rows = md.build_chain_like(CONFIRM, "chain", per=24, q2_key="q_eff")
    md.write(rows, "stories_chain_confirm.csv")
    print(f"confirm: {len(rows)} items / {len(CONFIRM)} scenarios")
